/**
 * CI failure triage (dev-cycle plan M4): turn a red CI log into a list of
 * failures, each with a root-cause class and the exact next command, so the
 * agent that reads it can act in one round.
 *
 * Pure parsing/classification — no I/O. `scripts/ci_failure_triage.ts` owns
 * reading the logs, the gate manifest and package.json.
 *
 * Classes (who acts on what: operations-hygiene runbook §1 "CI failure triage"):
 * - `generated-drift`       a freshness gate (`pnpm check`) found a stale generated file
 * - `ratchet/registration`  a ratchet / boundary / allowlist test or gate grew
 * - `gate-failure`          another `pnpm check` gate (or the type checker) failed
 * - `test-failure`          a Vitest test failed (`suspectedFlake` marks timing-shaped ones)
 * - `platform`              a test failed only in a macOS / Windows job
 * - `infra`                 install / checkout / network / runner trouble before tests ran
 * - `unknown`               nothing above matched — the first error block is attached
 */
import { createHash } from 'node:crypto';

export type CiFailureClass =
  | 'generated-drift'
  | 'ratchet/registration'
  | 'gate-failure'
  | 'test-failure'
  | 'platform'
  | 'infra'
  | 'unknown';

export interface CiFailure {
  class: CiFailureClass;
  /** Stable 12-hex identity of the failure (class + gate/file/test), used to dedupe issues. */
  signature: string;
  title: string;
  /** CI job the failure came from, when known. */
  job?: string;
  gate?: string;
  file?: string;
  test?: string;
  /** Assertion or violation lines that explain the failure. */
  evidence: string[];
  /** Commands to run next, most specific first. */
  next: string[];
  /** Repository doc that explains the remedy. */
  doc?: string;
  suspectedFlake?: boolean;
  /** Generated files a freshness gate reported as changed. */
  changed?: string[];
}

/** How to regenerate the output a freshness gate checks. */
export interface GateRemedy {
  /** Generator command, e.g. `pnpm generate:op-registry`. */
  generator?: string;
  /** The command that re-runs the gate alone. */
  check: string;
}

export interface TriageOptions {
  /** Default job name when the log carries none (`--job`). */
  job?: string;
  /** Per-gate remedies derived from ci-gates.json + package.json. */
  gateRemedies?: Readonly<Record<string, GateRemedy>>;
}

export interface TriageReport {
  ok: boolean;
  jobs: string[];
  failures: CiFailure[];
}

export const REGISTRATION_DOC = 'knowledge/product/governance/kyberion-development-practices.md';
export const PLATFORM_DOC =
  'knowledge/product/governance/kyberion-development-practices.md#2-cross-platform-determinism--the-linux-ci-rules';
export const TRIAGE_DOC = 'knowledge/product/governance/operations-hygiene-runbook.md';
export const RESOLVE_GENERATED_COMMAND = 'pnpm kyberion resolve generated';

/** Gate ids regenerated by `pnpm kyberion resolve generated` (scripts/resolve_generated.ts). */
export const RESOLVE_GENERATED_GATE_IDS: readonly string[] = [
  'env-registry',
  'knowledge-index',
  'role-assumption-reachability',
  'changelog-fragments',
];

/** Gates whose failure means a ratchet grew or a registration ceremony was skipped. */
const RATCHET_GATE_IDS = new Set([
  'type-ratchet',
  'foundation-adoption',
  'config-fallbacks',
  'module-boundaries',
  'max-file-lines',
  'i18n',
  'cli-manifest',
  'install-script-allowlist',
  'orphans',
  'esm',
  'dist-workspace-imports',
  'knowledge-scope',
  'op-effect-coverage',
  'op-input-contract-coverage',
  'op-preflight-coverage',
  'pipeline-op-schemas',
]);

const RATCHET_TEST_FILE = /(ratchet|boundar|allowlist|baseline|registration|governance-import)/iu;
const RATCHET_TEXT =
  /\bincreased from \d+ to \d+\b|\ballowlist\b|\bnot registered\b|\bbaseline\b/iu;

const FLAKE_TEXT =
  /timed? ?out|timeout|\bexpired?\b|\bttl\b|deadline|setTimeout|ETIMEDOUT|ECONNRESET|EADDRINUSE|flak/iu;
const FLAKE_TEST_NAME =
  /expir|\bttl\b|timeout|timer|debounce|throttle|retry|poll|interval|deadline|race/iu;

const INFRA_PATTERNS: ReadonlyArray<{ pattern: RegExp; why: string }> = [
  { pattern: /ERR_PNPM_[A-Z_]+/u, why: 'pnpm install failed' },
  { pattern: /npm ERR! (?:network|code E)/u, why: 'package registry error' },
  {
    pattern: /fatal: (?:unable to access|could not read|repository .* not found)/iu,
    why: 'git checkout failed',
  },
  { pattern: /getaddrinfo (?:ENOTFOUND|EAI_AGAIN)/u, why: 'DNS lookup failed' },
  {
    pattern: /Failed to fetch .*(?:archive\.ubuntu|apt)|E: Unable to fetch/u,
    why: 'apt mirror failed',
  },
  {
    pattern:
      /Unable to (?:download|find) artifact|Failed to (?:CreateArtifact|download artifact)/iu,
    why: 'artifact transfer failed',
  },
  { pattern: /No space left on device/u, why: 'runner disk full' },
  {
    pattern: /runner has received a shutdown signal|lost communication with the server/iu,
    why: 'runner lost',
  },
  { pattern: /has exceeded the maximum execution time/iu, why: 'job hit its timeout-minutes' },
  {
    pattern: /Unable to resolve action|Can't find 'action\.yml'/u,
    why: 'action could not be resolved',
  },
  {
    pattern: /API rate limit exceeded|HTTP 5\d\d|503 Service Unavailable/u,
    why: 'remote service unavailable',
  },
];

// eslint-disable-next-line no-control-regex
const ANSI = /\u001b\[[0-9;?]*[ -/]*[@-~]|\u001b\][^\u0007]*\u0007/gu;
const GH_TIMESTAMP = /^\uFEFF?\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z ?/u;

/** Strip ANSI colour codes, GitHub timestamp prefixes and `##[group]`-style markers. */
export function normalizeCiLine(line: string): string {
  return line
    .replace(ANSI, '')
    .replace(/\r$/u, '')
    .replace(GH_TIMESTAMP, '')
    .replace(/^##\[(?:group|endgroup)\]/u, '');
}

export interface CiLogSegment {
  job?: string;
  lines: string[];
}

/**
 * Split a log into per-job segments. `gh run view --log-failed` prefixes each
 * line with `<job>\t<step>\t<timestamp> `; a plain step log has no prefix and
 * becomes one segment attributed to `defaultJob`.
 */
export function splitCiLog(text: string, defaultJob?: string): CiLogSegment[] {
  const segments = new Map<string, string[]>();
  const order: string[] = [];
  const plainKey = '\u0000plain';
  for (const raw of text.split('\n')) {
    const stripped = raw.replace(ANSI, '').replace(/\r$/u, '');
    const prefixed = /^([^\t]+)\t([^\t]*)\t(.*)$/u.exec(stripped);
    const isGhPrefixed = prefixed !== null && GH_TIMESTAMP.test(prefixed[3]!);
    const key = isGhPrefixed ? prefixed[1]!.trim() : plainKey;
    const line = normalizeCiLine(isGhPrefixed ? prefixed[3]! : stripped);
    if (!segments.has(key)) {
      segments.set(key, []);
      order.push(key);
    }
    segments.get(key)!.push(line);
  }
  return order.map((key) => ({
    job: key === plainKey ? defaultJob : key,
    lines: segments.get(key)!,
  }));
}

export function failureSignature(parts: ReadonlyArray<string | undefined>): string {
  return createHash('sha256')
    .update(parts.filter(Boolean).join('|').replace(/\d+/gu, '#'))
    .digest('hex')
    .slice(0, 12);
}

export function isCrossOsJob(job: string | undefined): boolean {
  return job !== undefined && /\b(macos|windows)\b/iu.test(job);
}

function shellQuote(value: string): string {
  return `'${value.replace(/'/gu, `'\\''`)}'`;
}

// ---------------------------------------------------------------------------
// `pnpm check` gate blocks
// ---------------------------------------------------------------------------

const GATE_LINE = /^\s*- (FAILED|PASSED) ([A-Za-z0-9:_-]+)\s*$/u;
const GATE_BLOCK_END =
  /^\s*(?:- (?:FAILED|PASSED) |\[check\] |ELIFECYCLE|Error: Process completed|##\[error\])/u;

interface GateBlock {
  gate: string;
  lines: string[];
}

export function extractGateBlocks(lines: readonly string[]): GateBlock[] {
  const blocks: GateBlock[] = [];
  for (let index = 0; index < lines.length; index += 1) {
    const match = GATE_LINE.exec(lines[index]!);
    if (!match || match[1] !== 'FAILED') continue;
    const body: string[] = [];
    for (let cursor = index + 1; cursor < lines.length && body.length < 80; cursor += 1) {
      if (GATE_BLOCK_END.test(lines[cursor]!)) break;
      body.push(lines[cursor]!);
    }
    blocks.push({ gate: match[2]!, lines: body });
  }
  return blocks;
}

/** Files listed under `"changed": [ ... ]` in a generator's `--check` output. */
export function extractChangedFiles(lines: readonly string[]): string[] {
  const text = lines.join('\n');
  const match = /"changed"\s*:\s*\[([^\]]*)\]/u.exec(text);
  if (!match) return [];
  return [...match[1]!.matchAll(/"([^"]+)"/gu)].map((entry) => entry[1]!);
}

function evidenceLines(lines: readonly string[], limit = 8): string[] {
  return lines
    .map((line) => line.trimEnd())
    .filter((line) => line.trim() !== '')
    .slice(0, limit);
}

function classifyGate(
  block: GateBlock,
  job: string | undefined,
  options: TriageOptions
): CiFailure {
  const remedy = options.gateRemedies?.[block.gate];
  const checkCommand = remedy?.check ?? `pnpm check -- --only ${block.gate}`;
  const changed = extractChangedFiles(block.lines);
  const ratchetLines = block.lines.filter((line) => /increased from \d+ to \d+/u.test(line));
  const viaResolve = RESOLVE_GENERATED_GATE_IDS.includes(block.gate);

  if (remedy?.generator || viaResolve || changed.length > 0) {
    const next = [
      ...(remedy?.generator ? [remedy.generator] : []),
      ...(viaResolve || !remedy?.generator ? [RESOLVE_GENERATED_COMMAND] : []),
      checkCommand,
    ];
    return {
      class: 'generated-drift',
      signature: failureSignature(['generated-drift', block.gate]),
      title: `generated file drift in gate \`${block.gate}\``,
      job,
      gate: block.gate,
      evidence:
        changed.length > 0 ? changed.map((file) => `changed: ${file}`) : evidenceLines(block.lines),
      next: [...new Set(next)],
      doc: TRIAGE_DOC,
      ...(changed.length > 0 ? { changed } : {}),
    };
  }

  if (
    RATCHET_GATE_IDS.has(block.gate) ||
    ratchetLines.length > 0 ||
    RATCHET_TEXT.test(block.lines.join('\n'))
  ) {
    return {
      class: 'ratchet/registration',
      signature: failureSignature(['ratchet', block.gate]),
      title: `ratchet / registration gate \`${block.gate}\` failed`,
      job,
      gate: block.gate,
      evidence:
        ratchetLines.length > 0
          ? ratchetLines.map((line) => line.trim())
          : evidenceLines(block.lines),
      next: [checkCommand],
      doc: REGISTRATION_DOC,
    };
  }

  return {
    class: 'gate-failure',
    signature: failureSignature(['gate', block.gate]),
    title: `gate \`${block.gate}\` failed`,
    job,
    gate: block.gate,
    evidence: evidenceLines(block.lines),
    next: [checkCommand],
    doc: 'knowledge/product/governance/ci-gates.json',
  };
}

// ---------------------------------------------------------------------------
// Vitest failures
// ---------------------------------------------------------------------------

const VITEST_FAIL =
  /^\s*(?:FAIL|×|✗)\s+(?:\|[^|]+\|\s+)?(\S+\.(?:test|spec)\.[cm]?[jt]sx?)(?:\s+(?:>\s*(.+?)|\[[^\]]*\]))?\s*$/u;
const ASSERTION_LINE =
  /^\s*(?:[A-Za-z]*Error|AssertionError)\b[:\s]|^\s*(?:Expected|Received|expected)\b|^\s*-\s*Expected|^\s*\+\s*Received/u;

interface VitestFailure {
  file: string;
  test?: string;
  evidence: string[];
}

export function extractVitestFailures(lines: readonly string[]): VitestFailure[] {
  const byKey = new Map<string, VitestFailure>();
  for (let index = 0; index < lines.length; index += 1) {
    const match = VITEST_FAIL.exec(lines[index]!);
    if (!match) continue;
    const file = match[1]!;
    const test = match[2]?.trim();
    const evidence: string[] = [];
    for (let cursor = index + 1; cursor < Math.min(lines.length, index + 25); cursor += 1) {
      const line = lines[cursor]!;
      if (VITEST_FAIL.test(line)) break;
      if (ASSERTION_LINE.test(line)) evidence.push(line.trim());
      if (evidence.length >= 4) break;
    }
    const key = `${file}::${test ?? ''}`;
    const existing = byKey.get(key);
    if (!existing) byKey.set(key, { file, ...(test ? { test } : {}), evidence });
    else if (existing.evidence.length === 0) existing.evidence = evidence;
  }
  // A suite-level `FAIL file` entry adds nothing when a test in that file is listed.
  const withTests = new Set(
    [...byKey.values()].filter((entry) => entry.test).map((entry) => entry.file)
  );
  return [...byKey.values()].filter((entry) => entry.test || !withTests.has(entry.file));
}

function classifyTest(failure: VitestFailure, job: string | undefined): CiFailure {
  const testName = failure.test?.split('>').pop()?.trim();
  const rerun = `pnpm exec vitest run ${failure.file}${testName ? ` -t ${shellQuote(testName)}` : ''}`;
  const where = failure.test ? `${failure.file} > ${failure.test}` : failure.file;
  if (RATCHET_TEST_FILE.test(failure.file)) {
    return {
      class: 'ratchet/registration',
      signature: failureSignature(['ratchet', failure.file, failure.test]),
      title: `registration / ratchet test failed: ${where}`,
      job,
      file: failure.file,
      ...(failure.test ? { test: failure.test } : {}),
      evidence: failure.evidence,
      next: [rerun],
      doc: REGISTRATION_DOC,
    };
  }
  const suspectedFlake =
    FLAKE_TEXT.test(failure.evidence.join('\n')) || FLAKE_TEST_NAME.test(failure.test ?? '');
  return {
    class: 'test-failure',
    signature: failureSignature(['test', failure.file, failure.test]),
    title: `test failed: ${where}`,
    job,
    file: failure.file,
    ...(failure.test ? { test: failure.test } : {}),
    evidence: failure.evidence,
    next: suspectedFlake
      ? [rerun, `for i in $(seq 1 20); do ${rerun} || break; done   # reproduce the flake`]
      : [rerun],
    doc: suspectedFlake ? 'docs/developer/WRITING_TESTS.md' : undefined,
    suspectedFlake,
  };
}

// ---------------------------------------------------------------------------
// TypeScript, infra, unknown
// ---------------------------------------------------------------------------

const TS_ERROR =
  /^(.+?\.[cm]?tsx?)\(\d+,\d+\): error (TS\d+): (.*)$|^(.+?\.[cm]?tsx?):\d+:\d+ - error (TS\d+): (.*)$/u;

function extractTypeErrors(lines: readonly string[], job: string | undefined): CiFailure[] {
  const errors = lines.map((line) => TS_ERROR.exec(line.trim())).filter((match) => match !== null);
  if (errors.length === 0) return [];
  const files = [...new Set(errors.map((match) => match![1] ?? match![4]!))];
  return [
    {
      class: 'gate-failure',
      signature: failureSignature(['typecheck', ...files]),
      title: `TypeScript errors in ${files.length} file(s)`,
      job,
      gate: 'typecheck',
      evidence: errors.slice(0, 8).map((match) => match![0].trim()),
      next: ['pnpm typecheck'],
    },
  ];
}

function extractInfra(lines: readonly string[], job: string | undefined): CiFailure[] {
  for (const line of lines) {
    for (const { pattern, why } of INFRA_PATTERNS) {
      if (!pattern.test(line)) continue;
      return [
        {
          class: 'infra',
          signature: failureSignature(['infra', why]),
          title: `infrastructure: ${why}`,
          job,
          evidence: [line.trim()],
          next: [
            'gh run rerun <run-id> --failed   # re-run only the failed jobs',
            'if it repeats: check https://www.githubstatus.com and the step that failed before tests ran',
          ],
        },
      ];
    }
  }
  return [];
}

const ERROR_LINE = /##\[error\]|\berror\b|\bERR!|\bfailed\b|\bFAIL\b|Exception|Traceback/iu;
// Lines that mention "error" without being one: passing gates and tests,
// log-level WARN/INFO chatter, and zero-failure summaries.
const ERROR_NOISE =
  /^\s*- PASSED |^\s*[✓√]\s|\[(?:WARN|INFO|DEBUG)\]|\b0 failed\b|failed=0\b|--exit-on-missing|error-handling|\bno errors?\b/iu;

function extractUnknown(lines: readonly string[], job: string | undefined): CiFailure[] {
  const start = lines.findIndex((line) => ERROR_LINE.test(line) && !ERROR_NOISE.test(line));
  if (start === -1) return [];
  const block = evidenceLines(lines.slice(start, start + 12), 12);
  return [
    {
      class: 'unknown',
      signature: failureSignature(['unknown', block[0]?.replace(/\s+/gu, ' ')]),
      title: 'unclassified failure',
      job,
      evidence: block,
      next: ['gh run view <run-id> --log-failed   # read the full failed step log'],
      doc: TRIAGE_DOC,
    },
  ];
}

// ---------------------------------------------------------------------------
// Entry points
// ---------------------------------------------------------------------------

export function triageSegment(segment: CiLogSegment, options: TriageOptions = {}): CiFailure[] {
  const job = segment.job ?? options.job;
  const failures = [
    ...extractGateBlocks(segment.lines).map((block) => classifyGate(block, job, options)),
    ...extractVitestFailures(segment.lines).map((failure) => classifyTest(failure, job)),
    ...extractTypeErrors(segment.lines, job),
  ];
  if (failures.length > 0) return failures;
  const infra = extractInfra(segment.lines, job);
  return infra.length > 0 ? infra : extractUnknown(segment.lines, job);
}

/**
 * Triage a whole log (one step log, or `gh run view --log-failed` output with
 * many jobs). A test that fails only in macOS/Windows jobs becomes `platform`;
 * failures with the same signature in several jobs are reported once.
 */
export function triageCiLog(text: string, options: TriageOptions = {}): TriageReport {
  const segments = splitCiLog(text, options.job);
  const all = segments.flatMap((segment) => triageSegment(segment, options));
  const bySignature = new Map<string, CiFailure & { jobs: Set<string> }>();
  for (const failure of all) {
    const existing = bySignature.get(failure.signature);
    if (existing) {
      if (failure.job) existing.jobs.add(failure.job);
      continue;
    }
    bySignature.set(failure.signature, {
      ...failure,
      jobs: new Set(failure.job ? [failure.job] : []),
    });
  }
  const failures: CiFailure[] = [...bySignature.values()].map(({ jobs, ...failure }) => {
    const jobList = [...jobs];
    const job = jobList.length > 0 ? jobList.join(', ') : failure.job;
    const platformOnly =
      failure.class === 'test-failure' && jobList.length > 0 && jobList.every(isCrossOsJob);
    if (!platformOnly) return { ...failure, ...(job ? { job } : {}) };
    return {
      ...failure,
      class: 'platform',
      signature: failureSignature(['platform', failure.file, failure.test]),
      title: failure.title.replace(/^test failed/u, 'platform-only test failure'),
      job,
      doc: PLATFORM_DOC,
      // A test that only fails on the slow hosted runners is a flake candidate too.
      suspectedFlake: true,
    };
  });
  const jobs = [
    ...new Set(segments.map((segment) => segment.job).filter((job): job is string => Boolean(job))),
  ];
  return { ok: failures.length === 0, jobs, failures };
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

function markdownCell(value: string): string {
  // Escape backslashes first so an input `\|` cannot turn into an unescaped pipe.
  return value.replace(/\\/gu, '\\\\').replace(/\|/gu, '\\|').replace(/\n/gu, ' ');
}

export function renderFailureMarkdown(failure: CiFailure, heading = '###'): string {
  const lines = [
    `${heading} \`${failure.class}\`${failure.suspectedFlake ? ' (suspected flake)' : ''} — ${failure.title}`,
    '',
    ...(failure.job ? [`- job: ${failure.job}`] : []),
    `- signature: \`${failure.signature}\``,
    ...(failure.doc ? [`- doc: \`${failure.doc}\``] : []),
    '',
    'Next:',
    '',
    '```sh',
    ...failure.next,
    '```',
  ];
  if (failure.evidence.length > 0) {
    lines.push('', 'Evidence:', '', '```text', ...failure.evidence, '```');
  }
  return lines.join('\n');
}

export function renderTriageMarkdown(report: TriageReport): string {
  const header = '## CI failure triage';
  if (report.ok) {
    return `${header}\n\nNo recognizable failure in the captured output. Read the failed step log directly.\n`;
  }
  const rows = report.failures.map(
    (failure, index) =>
      `| ${index + 1} | \`${failure.class}\`${failure.suspectedFlake ? ' (flake?)' : ''} | ${markdownCell(failure.title)} | \`${markdownCell(failure.next[0] ?? '')}\` |`
  );
  return [
    header,
    '',
    `${report.failures.length} failure(s)${report.jobs.length > 0 ? ` in ${report.jobs.map((job) => `\`${job}\``).join(', ')}` : ''}. Who acts on which class: \`${TRIAGE_DOC}\` §1.`,
    '',
    '| # | Class | Failure | Next command |',
    '| - | ----- | ------- | ------------ |',
    ...rows,
    '',
    ...report.failures.map((failure) => renderFailureMarkdown(failure)),
    '',
  ].join('\n');
}
